// Focus loss must remove only composition ownership, never rewrite old/raw text.
#define WANGSHU_SELECTION_FIXTURES_ONLY
#include "selection_scope_test.cpp"
struct FocusFixture:SelectionFixture {~FocusFixture(){context->flush();}};
static int good=0,bad=0;
static void scenario(const char* name,const std::function<void()>& run){try{run();++good;std::cout<<"PASS "<<name<<std::endl;}catch(const std::exception& error){++bad;std::cout<<"FAIL "<<name<<" :: "<<error.what()<<std::endl;}}
static void leave(SelectionFixture& f){f.service->OnSetFocus(static_cast<ITfDocumentMgr*>(nullptr),static_cast<ITfDocumentMgr*>(nullptr));}
int main(){
    scenario("sync focus cleanup does not rewrite text or caret",[]{FocusFixture f;auto& d=f.context->document;auto before=d.text;leave(f);requireSelection(d.text==before&&d.textWrites==0&&d.selectionWrites==0&&TextServiceTestAccess::pendingText(f.service).empty(),"Focus cleanup rewrote text/caret");});
    scenario("deferred cleanup preserves moved caret",[]{FocusFixture f;auto& d=f.context->document;f.context->deferred=true;leave(f);d.start=d.end=2;auto before=d.text;f.context->flush();requireSelection(d.text==before&&d.start==2&&d.end==2&&d.textWrites==0&&d.selectionWrites==0,"Deferred cleanup rewrote current document/selection");});
    scenario("deferred cleanup preserves host-modified composition",[]{FocusFixture f;auto& d=f.context->document;f.context->deferred=true;leave(f);d.text.replace(6,5,L"fresh");auto before=d.text;f.context->flush();requireSelection(d.text==before&&d.textWrites==0&&d.selectionWrites==0,"Cleanup restored stale pinyin");});
    scenario("same-context reentry appends new composition without losing old pinyin",[]{FocusFixture f;auto& d=f.context->document;f.context->deferred=true;leave(f);BOOL eaten=FALSE;f.service->OnKeyDown(f.context,'K',0,&eaten);requireSelection(eaten&&d.text==L"beforenihaokafter"&&f.context->compositionStarts==2&&TextServiceTestAccess::pendingText(f.service)=="k","New key replaced old pinyin instead of starting separate composition");auto before=d.text;auto writes=d.textWrites;auto selections=d.selectionWrites;f.context->flush();requireSelection(d.text==before&&d.textWrites==writes&&d.selectionWrites==selections&&TextServiceTestAccess::pendingText(f.service)=="k","Old ending callback affected new composition");f.service->OnKeyDown(f.context,VK_RETURN,0,&eaten);requireSelection(eaten&&d.text==before&&TextServiceTestAccess::pendingText(f.service).empty(),"New composition cannot complete after old ending callback");});
    scenario("different-context first key works while old cleanup waits",[]{FocusFixture f;f.context->deferred=true;leave(f);auto* other=new SelectionContext;auto* document=new DocumentManager(other);auto* previous=f.manager->document;f.manager->document=document;other->documentManager=document;previous->Release();BOOL eaten=FALSE;f.service->OnKeyDown(other,'K',0,&eaten);auto current=other->document.text;bool accepted=eaten&&current==L"beforekafter"&&other->compositionStarts==1;f.context->flush();bool untouched=other->document.text==current&&TextServiceTestAccess::pendingText(f.service)=="k";f.service->OnKeyDown(other,VK_RETURN,0,&eaten);other->Release();requireSelection(accepted&&untouched,"Old context ownership blocked or modified the first new-context key");});
    scenario("rejected cleanup request preserves data and permits fresh ownership",[]{FocusFixture f;auto& d=f.context->document;auto before=d.text;f.context->denyEditRequest=true;leave(f);requireSelection(d.text==before&&d.textWrites==0&&d.selectionWrites==0,"Rejected cleanup changed text");f.context->denyEditRequest=false;BOOL eaten=FALSE;f.service->OnKeyDown(f.context,'K',0,&eaten);requireSelection(eaten&&d.text==L"beforenihaokafter"&&f.context->compositionStarts==2,"Refused cleanup retained stale active ownership");});
    scenario("deactivation before deferred cleanup retains host text",[]{FocusFixture f;auto& d=f.context->document;f.context->deferred=true;leave(f);f.service->Deactivate();auto before=d.text;f.context->flush();requireSelection(d.text==before&&d.textWrites==0&&d.selectionWrites==0,"Post-deactivation cleanup wrote host text");});
    scenario("focus fixtures release all COM ownership",[]{requireSelection(objectCount==0,"Focus fixture retained COM service ownership");});
    std::cout<<"RESULT passed="<<good<<" failed="<<bad<<" total="<<(good+bad)<<"; actual PE production TSF controlled focus host; real Windows NOT_RUN"<<std::endl;return bad?1:0;
}
